-- FormDev registry for MySQL (migration 2): styles, fonts and lookup tables from formdev/registry/.
-- Generated by formdev/scripts/sync_registry_seed.py; do not edit.
AS new
ON DUPLICATE KEY UPDATE metadata = new.metadata, updated_at = IF(formdev_font.metadata <> new.metadata, new.updated_at, formdev_font.updated_at);

AS new
ON DUPLICATE KEY UPDATE definition = IF(new.version > formdev_style.version, new.definition, formdev_style.definition),
  updated_at = IF(new.version > formdev_style.version, new.updated_at, formdev_style.updated_at),
  version = GREATEST(formdev_style.version, new.version);

AS new
ON DUPLICATE KEY UPDATE metadata = IF(new.version > formdev_lookup.version, new.metadata, formdev_lookup.metadata),
  entries = IF(new.version > formdev_lookup.version, new.entries, formdev_lookup.entries),
  updated_at = IF(new.version > formdev_lookup.version, new.updated_at, formdev_lookup.updated_at),
  updated_by = IF(new.version > formdev_lookup.version, new.updated_by, formdev_lookup.updated_by),
  version = GREATEST(formdev_lookup.version, new.version);
