INSERT INTO formdev_style (style_id, version, definition, updated_at) VALUES
  ('style.base', 1, '{"name":"Base","category":"base","tokens":{"fontId":"noto-sans-thai","fontSize":11,"fontWeight":400,"lineHeight":1.4,"color":"#1f2937","background":"transparent","align":"left","labelPosition":"top","border":"solid","borderColor":"#cbd5e1","radius":1.5,"padding":1.5,"gap":3,"columns":2,"inputHeight":8,"rule":"solid","uppercase":false,"pageMarginTop":15,"pageMarginRight":15,"pageMarginBottom":15,"pageMarginLeft":15},"components":{"label":{"fontSize":10,"fontWeight":600,"color":"#475569"},"section":{"fontSize":12,"fontWeight":700,"color":"#0f172a"},"header":{"fontSize":9,"color":"#64748b"},"footer":{"fontSize":9,"color":"#64748b"}}}', 0),
  ('style.a4.default', 1, '{"name":"A4 default","category":"form","inherit":"style.base","paper":"A4","tokens":{"fontSize":11}}', 0),
  ('style.a4.medical', 1, '{"name":"A4 medical record","category":"form","inherit":"style.a4.default","paper":"A4","tokens":{"fontSize":10,"pageMarginTop":12,"pageMarginRight":12,"pageMarginBottom":14,"pageMarginLeft":12,"rule":"solid"},"components":{"label":{"fontSize":9},"section":{"fontSize":11}}}', 0),
  ('style.a4.official', 1, '{"name":"A4 official document","category":"form","inherit":"style.a4.default","paper":"A4","tokens":{"fontId":"th-sarabun-new","fontSize":16,"columns":1,"rule":"none","border":"underline","pageMarginTop":25,"pageMarginRight":20,"pageMarginBottom":20,"pageMarginLeft":30},"components":{"label":{"fontSize":16,"fontWeight":400,"color":"#000000"},"section":{"fontSize":16,"fontWeight":700,"color":"#000000"}}}', 0),
  ('style.a4.compact', 1, '{"name":"A4 compact","category":"form","inherit":"style.a4.default","paper":"A4","tokens":{"fontSize":9,"gap":1.5,"padding":1,"inputHeight":6,"columns":3,"pageMarginTop":10,"pageMarginRight":10,"pageMarginBottom":10,"pageMarginLeft":10},"components":{"label":{"fontSize":8},"section":{"fontSize":10}}}', 0),
  ('field.text.default', 1, '{"name":"Text field","category":"field","tokens":{"border":"solid","inputHeight":8}}', 0),
  ('field.number.large', 1, '{"name":"Large number","category":"field","inherit":"field.text.default","tokens":{"fontSize":16,"fontWeight":700,"align":"right"}}', 0),
  ('section.header', 1, '{"name":"Header section","category":"section","tokens":{"rule":"card","background":"#f1f5f9","padding":3},"components":{"section":{"fontSize":13,"uppercase":true}}}', 0),
  ('form.a4.medical', 2, '{"name":"A4 medical record (alias of style.a4.medical)","category":"form","inherit":"style.a4.medical","paper":"A4","tokens":{}}', 0),
  ('form.a4.official', 2, '{"name":"A4 official document (alias of style.a4.official)","category":"form","inherit":"style.a4.official","paper":"A4","tokens":{}}', 0),
