  ('thai_address', 1, '{"title":"ที่อยู่ประเทศไทย (จังหวัด / อำเภอ / ตำบล / รหัสไปรษณีย์)","columns":[{"name":"province","label":"จังหวัด"},{"name":"district","label":"อำเภอ / เขต"},{"name":"subdistrict","label":"ตำบล / แขวง"},{"name":"postcode","label":"รหัสไปรษณีย์"}],"authoritative":false,"notice":"SAMPLE ONLY: a handful of rows for development and tests, not a complete or verified list. Import the official dataset with formdev/scripts/import_lookup.py before production use."}', '[{"province":"กรุงเทพมหานคร","district":"เขตพระนคร","subdistrict":"แขวงพระบรมมหาราชวัง","postcode":"10200"},{"province":"กรุงเทพมหานคร","district":"เขตพระนคร","subdistrict":"แขวงวังบูรพาภิรมย์","postcode":"10200"},{"province":"กรุงเทพมหานคร","district":"เขตพระนคร","subdistrict":"แขวงวัดราชบพิธ","postcode":"10200"},{"province":"กรุงเทพมหานคร","district":"เขตปทุมวัน","subdistrict":"แขวงลุมพินี","postcode":"10330"},{"province":"กรุงเทพมหานคร","district":"เขตปทุมวัน","subdistrict":"แขวงรองเมือง","postcode":"10330"},{"province":"กรุงเทพมหานคร","district":"เขตบางรัก","subdistrict":"แขวงสีลม","postcode":"10500"},{"province":"เชียงใหม่","district":"อำเภอเมืองเชียงใหม่","subdistrict":"ตำบลศรีภูมิ","postcode":"50200"},{"province":"เชียงใหม่","district":"อำเภอเมืองเชียงใหม่","subdistrict":"ตำบลสุเทพ","postcode":"50200"},{"province":"เชียงใหม่","district":"อำเภอเมืองเชียงใหม่","subdistrict":"ตำบลช้างเผือก","postcode":"50300"},{"province":"เชียงใหม่","district":"อำเภอสันทราย","subdistrict":"ตำบลสันทรายหลวง","postcode":"50210"},{"province":"ขอนแก่น","district":"อำเภอเมืองขอนแก่น","subdistrict":"ตำบลในเมือง","postcode":"40000"},{"province":"ภูเก็ต","district":"อำเภอเมืองภูเก็ต","subdistrict":"ตำบลตลาดใหญ่","postcode":"83000"},{"province":"ภูเก็ต","district":"อำเภอกะทู้","subdistrict":"ตำบลป่าตอง","postcode":"83150"}]', 0, 'system')
